/**
 * Backend search tool used by TravelNewsService to gather verifiable travel news
 * from public RSS sources before passing results to the AI. This tool performs
 * the actual network retrieval itself (no reliance on model tool/function calling).
 */
@Injectable()
export class TravelNewsSearchTool {
  private readonly logger = new Logger(TravelNewsSearchTool.name);

  async search(language: 'ar' | 'en'): Promise<TravelNewsArticle[]> {
    const results = await Promise.allSettled(
      FEEDS.map(async ({ category, query }) => {
        const parameters = new URLSearchParams({
          q: query,
          hl: language === 'ar' ? 'ar' : 'en-US',
          gl: language === 'ar' ? 'EG' : 'US',
          ceid: language === 'ar' ? 'EG:ar' : 'US:en',
        });
        const response = await fetch(
          `https://news.google.com/rss/search?${parameters.toString()}`,
          {
            headers: {
              Accept: 'application/rss+xml, application/xml, text/xml',
            },
            signal: AbortSignal.timeout(8_000),
          },
        );
        if (!response.ok) {
          throw new Error(`News RSS returned HTTP ${response.status}`);
        }
        const xml = await response.text();
        if (Buffer.byteLength(xml, 'utf8') > MAX_FEED_BYTES) {
          throw new Error('News RSS response exceeded the size limit');
        }
        return parseTravelRss(xml, category);
      }),
    );

    const articles = results
      .filter(
        (result): result is PromiseFulfilledResult<TravelNewsArticle[]> =>
          result.status === 'fulfilled',
      )
      .flatMap((result) => result.value)
      .filter(
        (article, index, all) =>
          all.findIndex((candidate) => candidate.url === article.url) === index,
      )
      .sort(
        (left, right) =>
          (right.publishedAt ? Date.parse(right.publishedAt) : 0) -
          (left.publishedAt ? Date.parse(left.publishedAt) : 0),
      )
      .slice(0, MAX_ARTICLES);

    return articles;
  }
}

@Injectable()
export class TravelNewsService {
  private readonly logger = new Logger(TravelNewsService.name);
  private readonly inFlight = new Map<string, Promise<TravelNewsFeed>>();

  constructor(
    private readonly cache: CacheService,
    @Inject(AI_PROVIDER) private readonly ai: AiProvider,
    private readonly searchTool: TravelNewsSearchTool = new TravelNewsSearchTool(),
  ) {}

